(function(root){
 const API={
  fresh(){return {version:1,started:false,name:'',lens:'wander',current:0,collected:{},solved:{},completed:[],finalSelection:[],reflection:'',finished:false}},
  normalize(value,levels){let s=Object.assign(API.fresh(),value&&value.version===1?value:{});s.name=String(s.name||'').slice(0,30);s.reflection=String(s.reflection||'').slice(0,5000);s.lens=['wander','collect','research'].includes(s.lens)?s.lens:'wander';let collected=s.collected&&typeof s.collected==='object'?s.collected:{};s.collected={};levels.forEach(l=>{if(Array.isArray(collected[l.id]))s.collected[l.id]=[...new Set(collected[l.id].filter(id=>l.clues.some(c=>c[0]===id)))]});s.solved=s.solved&&typeof s.solved==='object'?s.solved:{};s.completed=Array.isArray(s.completed)?s.completed.filter(id=>levels.some(l=>l.id===id)):[];let n=0;while(n<levels.length-1&&s.completed.includes(levels[n].id))n++;s.completed=levels.slice(0,n).map(l=>l.id);s.current=Math.max(0,Math.min(Number.isInteger(s.current)?s.current:0,n));s.finalSelection=Array.isArray(s.finalSelection)?[...new Set(s.finalSelection.filter(k=>API.inventory(s,levels).some(c=>c.key===k)))]:[];s.finished=!!s.finished&&n===levels.length-1&&API.canFinish(s,levels);return s},
  unlocked(s,levels){let i=0;while(i<levels.length-1&&s.completed.includes(levels[i].id))i++;return i},
  collect(s,level,id){if(!level.clues.some(c=>c[0]===id))return false;let a=s.collected[level.id]||(s.collected[level.id]=[]);if(!a.includes(id))a.push(id);return true},
  connect(s,level,pair,answer){if(pair.length!==2||!level.pair.every(id=>pair.includes(id))||!pair.every(id=>(s.collected[level.id]||[]).includes(id)))return {ok:false,reason:'请从已搜集的碎片中，找到与当前问题直接相关的两份材料。'};if(Number(answer)!==level.answer)return {ok:false,reason:'这个解释还没有充分连接两条线索。请回看材料，或者使用提示。'};s.solved[level.id]=true;return {ok:true,reason:level.explanation}},
  complete(s,levels,index){let level=levels[index];if(index>API.unlocked(s,levels)||!s.solved[level.id])return false;if(!s.completed.includes(level.id))s.completed.push(level.id);s.current=Math.min(index+1,levels.length-1);return true},
  inventory(s,levels){return levels.flatMap(l=>(s.collected[l.id]||[]).map(id=>{let c=l.clues.find(c=>c[0]===id);return c?{key:l.id+':'+id,id,level:l.id,act:l.act,label:c[1],clue:c}:null}).filter(Boolean))},
  canFinish(s,levels){let inventory=API.inventory(s,levels),selected=s.finalSelection.map(k=>inventory.find(c=>c.key===k)).filter(Boolean);return API.unlocked(s,levels)===levels.length-1&&selected.length===3&&new Set(selected.filter(c=>c.act>0).map(c=>c.act)).size>=3&&String(s.reflection).trim().length>=8},
  source(clue,chapters){let pool=chapters.filter(c=>clue[3].includes(c.id));for(let c of pool){let i=c.paragraphs.findIndex(p=>p.length>35&&clue[4].some(t=>p.includes(t)));if(i>=0)return {chapter:c.id,title:c.title,pos:i,text:c.paragraphs[i],matched:true}}let c=pool.find(c=>c.paragraphs.length);if(!c)return null;let i=c.paragraphs.findIndex(p=>p.length>60);if(i<0)i=0;return {chapter:c.id,title:c.title,pos:i,text:c.paragraphs[i],matched:false}}
 };if(typeof module!=='undefined'&&module.exports)module.exports=API;else root.JourneyCore=API;
})(typeof window==='undefined'?this:window);
